import 'package:drift/drift.dart';
import 'package:drift_flutter/drift_flutter.dart';

// Generated by: dart run build_runner build --delete-conflicting-outputs
part 'app_database.g.dart';

/// One row per imported source (summary, note, article, ...).
///
/// The data class is renamed to [SourceRow] so it never clashes with the
/// domain model `KnowledgeSource`.
@DataClassName('SourceRow')
@TableIndex(name: 'idx_library_sources_fingerprint', columns: {#fingerprint})
class LibrarySources extends Table {
  TextColumn get id => text()();
  TextColumn get title => text()();
  TextColumn get author => text().nullable()();

  /// `SourceType.name` (for example "summary"). Stored as a name, not an
  /// index, so reordering the enum later cannot corrupt saved data.
  TextColumn get type => text()();

  DateTimeColumn get importedAt => dateTime()();

  /// Normalised-text hash used for duplicate detection.
  TextColumn get fingerprint => text()();

  IntColumn get chunkCount => integer()();

  @override
  Set<Column> get primaryKey => {id};
}

/// One row per passage. [content] is not called `text` because a getter named
/// `text` would clash with drift's `text()` column builder.
@DataClassName('ChunkRow')
@TableIndex(name: 'idx_library_chunks_source', columns: {#sourceId})
class LibraryChunks extends Table {
  TextColumn get id => text()();
  TextColumn get sourceId =>
      text().references(LibrarySources, #id, onDelete: KeyAction.cascade)();
  IntColumn get position => integer()();
  TextColumn get content => text()();

  /// Only set when the import carried an explicit chapter. Never guessed.
  TextColumn get chapter => text().nullable()();

  /// Only set when the import carried an explicit page. Never guessed.
  IntColumn get page => integer().nullable()();

  @override
  Set<Column> get primaryKey => {id};
}

@DriftDatabase(tables: [LibrarySources, LibraryChunks])
class AppDatabase extends _$AppDatabase {
  /// Opens the on-device database (file on Android/Windows, IndexedDB/OPFS on
  /// web when the web assets are present).
  AppDatabase() : super(_openConnection());

  /// For tests: pass `NativeDatabase.memory()`.
  AppDatabase.forTesting(super.executor);

  @override
  int get schemaVersion => 1;

  @override
  MigrationStrategy get migration => MigrationStrategy(
        onCreate: (m) => m.createAll(),
        beforeOpen: (details) async {
          // SQLite ignores foreign keys unless this is switched on per
          // connection. It makes "delete source" cascade to its chunks.
          await customStatement('PRAGMA foreign_keys = ON');
        },
      );

  static QueryExecutor _openConnection() {
    return driftDatabase(
      name: 'lifemaxxing',
      // Only used on Chrome. Needs web/sqlite3.wasm and web/drift_worker.js.
      web: DriftWebOptions(
        sqlite3Wasm: Uri.parse('sqlite3.wasm'),
        driftWorker: Uri.parse('drift_worker.js'),
      ),
    );
  }
}
